// Validate before the value ever reaches a shell.
const raw = ($json.body && $json.body.domain) || $json.domain || '';
const domain = String(raw).trim().toLowerCase();
if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(domain)) {
  throw new Error('invalid domain: ' + raw);
}
const selectors = ($json.body && $json.body.selectors) || '';
if (selectors && !/^[a-z0-9,._-]+$/.test(selectors)) {
  throw new Error('invalid selectors');
}
return [{ json: { domain, selectors } }];

const out = $json.stdout || '';
let reports;
try { reports = JSON.parse(out); }
catch (e) { throw new Error('audit produced no JSON: ' + out.slice(0, 300)); }
const summary = reports.map(r => ({
  domain: r.domain, verdict: r.verdict,
  failures: ['mx','spf','dkim','dmarc']
    .filter(k => r[k].verdict === 'FAIL')
    .map(k => k.toUpperCase()),
  warnings: ['mx','spf','dkim','dmarc']
    .filter(k => r[k].verdict === 'WARN')
    .map(k => k.toUpperCase()),
}));
return [{ json: {
  ok: summary.every(s => s.verdict !== 'FAIL'),
  summary,
  reports,
} }];
